import sys
from collections import defaultdict

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    events = defaultdict(list)
    for i in range(n):
        name = data[1 + 3 * i]
        s = int(data[2 + 3 * i])
        e = int(data[3 + 3 * i])
        events[s].append((name, 1))
        events[e].append((name, -1))
    count = defaultdict(int)
    active = set()
    out = []
    seg_start = None
    for t in sorted(events):
        before = {}
        for name, d in events[t]:
            if name not in before:
                before[name] = count[name] > 0
            count[name] += d
        flipped = [nm for nm, was in before.items() if (count[nm] > 0) != was]
        if not flipped:
            continue
        if seg_start is not None:
            names = sorted(active)
            line = f'{seg_start} {t} {len(names)}'
            if names:
                line += ' ' + ' '.join(names)
            out.append(line)
        for nm in flipped:
            if count[nm] > 0:
                active.add(nm)
            else:
                active.discard(nm)
        seg_start = t
    sys.stdout.write('\n'.join(out) + '\n')

