    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        String[] names = new String[n];
        long[] starts = new long[n], ends = new long[n];
        for (int i = 0; i < n; i++) {
            names[i] = st.nextToken();
            starts[i] = Long.parseLong(st.nextToken());
            ends[i] = Long.parseLong(st.nextToken());
        }
        StringBuilder sb = new StringBuilder();
        for (Segment seg : buildTimeline(names, starts, ends)) {
            sb.append(seg.start).append(' ').append(seg.end).append(' ').append(seg.names.size());
            for (String nm : seg.names) sb.append(' ').append(nm);
            sb.append('\n');
        }
        System.out.print(sb);
    }
